cp /etc/nftables.nft /etc/nftables.nft.pre-task && cat > /etc/nftables.nft <<'ANTRIEB_NFT_EOF'
#!/usr/sbin/nft -f
flush ruleset

table inet host_filter {
    chain input {
        type filter hook input priority filter; policy accept;

        tcp dport 22 counter accept comment "Allow SSH from any address"
        ip saddr 10.100.44.11 tcp dport 9000 counter accept comment "Allow TCP 9000 from node2"
        tcp dport 9000 counter reject with tcp reset comment "Reject TCP 9000 from all other sources"
        ct state { established, related } accept
    }
}
ANTRIEB_NFT_EOF
nft -c -f /etc/nftables.nft && printf '%s\n' 'syntax=valid'

